def zr(th, lev='0.25'):
    e = ZA['thresholds'][th][lev]
    lo, hi = e['point']

    def r_(x, ci):
        hw = (ci[1] - ci[0]) / 2
        return f'{round(x * 2) / 2:g}' if hw > 0.5 else f'{x:.1f}'
    return f"{r_(lo, e['lower_limit_ci'])}–{r_(hi, e['upper_limit_ci'])}"
