def para_words(ps):
    return sum((len(re.sub('\\[\\[[^\\]]+\\]\\]', '', s).replace('**', '').split()) for s in ps))

def sig2(x):
    m = 10 ** (int(math.floor(math.log10(abs(x)))) - 1)
    return int(round(x / m) * m)

def abstract():
    recs = sorted((float(rec(e)) for _, e, _, _ in ETH))
    lo4 = min((e['loss_fraction_single'] for e in (e3, e5, e75, e30)))
    hi4 = max((e['loss_fraction_single'] for e in (e3, e5, e75, e30)))
    return ['**Background:** PREVENT 10-year risk estimates enter the 2026 dyslipidemia and 2025 blood pressure guidelines, usually from one measurement set. We estimated how often the atherosclerotic cardiovascular disease (ASCVD) risk category and derived recommendations change on remeasurement, where, and how much expected net benefit is at stake.', f"**Methods:** In NHANES III, {pr['n']} adults aged 30–79 years without cardiovascular disease were reexamined under the same protocol a median of {iv['median']:.0f} days later, with blood pressure, lipids, creatinine, HbA1c and urine albumin-to-creatinine ratio (UACR) remeasured. The prespecified outcome was the proportion changing base PREVENT-ASCVD category (thresholds 3%, 5%, 10%). Post hoc analyses under prior protocols applied the 2025 and 2026 treatment rules to each examination and a decision-curve measurement-error model; NHANES 2009–2010 (n = {pa['n']:,}) isolated the urine specimen effect.", f"**Results:** {pr['events']} participants ({cis(pr)}) changed category. The chance of a change was {100 * min(pi0):.0f}–{100 * max(pi0):.0f}% at a threshold and ≥25% only within about {ZTXT} first-visit risk; blood pressure and lipids contributed {F(K2['Psi']['BP']['pp'])} and {F(K2['Psi']['LIPID']['pp'])} percentage points. A single-examination recommendation to start antihypertensive medication changed for {P(x3['theta_rx']['estimate'])}% ({cin(x3['theta_rx'])}) of {x3['n_untreated_eligible']} untreated participants, and a Class 1 statin recommendation for {P(V['primary_recommended_change']['estimate'])}% ({cin(V['primary_recommended_change'])}) of {V['n']} not taking a statin. Single-visit decisions forfeited {P(lo4)}–{P(hi4)}% of the net benefit achievable by deciding on the short-term mean level at the 3%, 5%, 7.5% and 30-year 10% thresholds and {lfs(e10)} at the 10% threshold; remeasurement within the zones recovered {recs[0]:.0f}–{recs[-1]:.0f}% of the loss. The specimen change altered {P(pa['estimate'])}% ({cin(pa)}) of UACR-model categories.", '**Conclusions:** In 1988–1994 data, 1 in 10 adults changed PREVENT category on remeasurement, within narrow zones around the thresholds, and the changes reached current treatment rules. Because those affected lie close to a threshold, the expected net benefit at stake is small; the cost is inconsistent advice, which targeted remeasurement can limit.']

def clinical_perspective():
    return [('h2', 'What Is New?'), ('p', f"• Remeasuring every PREVENT input under the same protocol about 2 weeks later (1988–1994) changed the 10-year ASCVD category of {P(pr['estimate'])}% of adults, nearly always within narrow zones around the 3%, 5% and 10% thresholds."), ('p', f"• Single-examination recommendations changed on remeasurement for {P(x3['theta_rx']['estimate'])}% of untreated adults under the 2025 blood pressure rule (unconfirmed office readings) and {P(V['primary_recommended_change']['estimate'])}% under the 2026 Class 1 statin rule."), ('p', f'• In a measurement-error model, single-visit decisions forfeited 1% or less of the achievable net benefit at the 3%, 5% and 7.5% thresholds ({lfs(e10)} at 10%), because those who change decision lie close to the threshold.'), ('h2', 'What Are the Clinical Implications?'), ('p', f'• A PREVENT category or risk-threshold recommendation within the zones (about {ZTXT} 10-year ASCVD risk) is provisional, and in the model a second measurement day for these adults removed about a quarter of category disagreement and {min((float(rec(e)) for _, e, _, _ in ETH)):.0f}–{max((float(rec(e)) for _, e, _, _ in ETH)):.0f}% of the small net-benefit loss at a fraction of the workload of repeating everyone.'), ('p', "• The data are consistent with the blood pressure guideline's requirement for readings on two occasions and show where a single lipid profile and risk estimate leave advice provisional, without showing that single-visit decisions cause measurable harm in expectation.")]
ABBREV = 'ASCVD, atherosclerotic cardiovascular disease; BP, blood pressure; CKD-EPI, Chronic Kidney Disease Epidemiology Collaboration; CVD, cardiovascular disease; eGFR, estimated glomerular filtration rate; HbA1c, hemoglobin A1c; LDL-C, low-density lipoprotein cholesterol; NCHS, National Center for Health Statistics; NHANES, National Health and Nutrition Examination Survey; PCE, Pooled Cohort Equations; PREVENT, Predicting Risk of Cardiovascular Disease Events; RCV, reference change value; SBP, systolic blood pressure; UACR, urine albumin-to-creatinine ratio'

def intro():
    return ['The PREVENT equations estimate 10-year atherosclerotic cardiovascular disease (ASCVD) and total cardiovascular disease (CVD) risk from age, sex, blood pressure, cholesterol, diabetes, smoking, kidney function and treatment, with urine albumin-to-creatinine ratio (UACR) as an optional input.[[khan2024]] Their categories now carry decisions: the 2026 dyslipidemia guideline recommends a statin at 10-year ASCVD risk ≥5% and treats 3–<5% as a range in which a statin is reasonable, and the 2025 high blood pressure guideline uses a 10-year total CVD risk of 7.5% for medication in stage 1 hypertension.[[dyslipidemia2026,htn2025,khan2025]] The dyslipidemia guideline recommends one lipid profile for risk estimation, with repeat testing only in specific situations.[[dyslipidemia2026]] A category is usually assigned from one visit, although blood pressure and laboratory analytes vary within a person from day to day.[[muntner2019,fraser1989]]', 'How much that variation moves people across risk thresholds has been studied in parts. Two decades ago, 103 patients with diabetes had cholesterol and blood pressure remeasured 2 weeks apart; 12% changed Framingham category, and the authors judged one assessment sufficient.[[lambert2002]] A simulation of biological and analytical variation at Framingham thresholds reached the opposite conclusion.[[reynolds2002]] Later work remeasured one or two inputs,[[ye2014,ulbricht2018,ogunwale2016]] bounded the effect of input uncertainty on Pooled Cohort Equations (PCE) categories,[[gupta2016]] or simulated lipid variation alone.[[cole2023]] Averaging repeated measurements modestly improves prediction.[[bell2012,paige2017]] For PREVENT, analyses have used hypothetical profiles or equation variants,[[krishnan2026,wilson2026]] and national eligibility estimates rest on a single measurement set.[[essa2026,spitz2026]] We found no study that remeasured all PREVENT inputs in a national survey sample, apportioned the category changes among them, or asked what they cost in expected net benefit.', f"We used the NHANES III second examination, in which the same protocol was repeated a median of {iv['median']:.0f} days later, to estimate how often, why and where the PREVENT category changes when every routinely measured input is remeasured (Study 1), and the NHANES 2009–2010 paired urine specimens to isolate the specimen effect on UACR (Study 2). In post hoc analyses, most under dated protocols saved before computation, we applied the 2025 and 2026 treatment rules to both examinations and modelled the expected net benefit forfeited by single-visit decisions and recovered by repeat measurement."]

def methods():
    b = []
    p = lambda s: b.append(('p', s))
    h2 = lambda s: b.append(('h2', s))
    h2('Design and Participants')
    p(f"Study 1 used the Third National Health and Nutrition Examination Survey (NHANES III, 1988–1994), in which the National Center for Health Statistics (NCHS) invited a nonrandom subsample of about 5% of examinees to a second mobile examination center examination that repeated the first under the same protocol, by the same teams, in the same session of the day.[[nhanes3_plan,nhanes3_files,nhanes3_secondexam]] Of 1,859 second examinations, 979 participants were aged 30–79 years, reported no myocardial infarction, stroke or heart failure and were not pregnant, and {pr['n']} had complete base PREVENT inputs at both examinations (analysis set; the 220 without a complete pair are compared with them in Supplemental Table S40); {K1['theta_U']['n']} also had UACR at both (Supplemental Figure S1). The interval between examinations was {iv['min']:.0f}–{iv['max']:.0f} days (median {iv['median']:.0f}; interquartile range {iv['q1']:.0f}–{iv['q3']:.0f}). The subsample is unweighted; its 98 pseudo-primary sampling units serve as variance clusters. Study 2 used NHANES 2009–2010, in which participants provided a random urine specimen at the examination and a first-morning specimen at home within 10 days;[[nh_albcr_f]] {pa['n']:,} adults aged 30–79 years without self-reported CVD, not pregnant, with both specimens and complete PREVENT inputs were analysed with examination weights, with inverse-probability response weighting as a sensitivity analysis. NHANES protocols were approved by the NCHS Research Ethics Review Board with written informed consent;[[nchs_erb]] this secondary analysis used deidentified public data.")
    h2('Measurements and Risk Equations')
    p('Remeasured inputs were systolic blood pressure (SBP; mean of the second and third mercury readings), total and HDL cholesterol, serum creatinine (kinetic Jaffe, calibrated to isotope dilution mass spectrometry-traceable values[[selvin2007]]) with eGFR from the race-free 2021 CKD-EPI equation,[[inker2021]] diabetes (self-reported diabetes or medication, insulin use, or HbA1c ≥6.5% at that examination, so that diabetes status itself could change; a sensitivity analysis holds it fixed) and UACR. Age, sex, smoking, antihypertensive treatment and statin use came from the interview and were fixed. The primary model was the base PREVENT 10-year ASCVD equation; secondary models were the UACR-enhanced 10-year ASCVD, the base 10-year total CVD and the base 30-year ASCVD equations,[[khan2024]] implemented from the published coefficient tables[[preventr]] and verified against an independent implementation[[pyprevent]] (maximum difference <10⁻¹³ percentage points [pp]). Inputs outside the PREVENT domain (SBP 90–200 mm Hg, total cholesterol 130–320 mg/dL, HDL cholesterol 20–100 mg/dL, eGFR 15–140 mL/min/1.73 m²) were set to the nearest bound (49 participants). Categories were <3%, 3–<5%, 5–<10% and ≥10%, with inclusive lower bounds.')
    h2('Prespecified Outcomes and Analyses')
    p("The Study 1 protocol was frozen, with a recorded hash, before any risk was scored (Supplemental Methods). The primary outcome was the proportion whose base PREVENT-ASCVD category differed between examinations (θ). Secondary outcomes were the same proportion for the UACR model and its paired difference from the base model; the contribution of each input group (blood pressure, lipids, creatinine, HbA1c and, in the UACR model, urine) by exact symmetrized Shapley values, the average contribution of a group over all orders of remeasuring the groups, which sum to θ;[[shapley1953]] the probability of a change as a function of the logit distance from the nearest threshold (restricted cubic spline logistic regression), conditioning either on first-visit risk (π_clin, the clinically available quantity, which includes regression to the mean) or on the mean of both visits (which removes it); the 95% reference change value (RCV) of risk;[[fraser1989]] θ standardized to the 9,478 weighted eligible examinees by applying the π_clin curve to their first-visit risk distribution (which assumes the same within-person variation); the proportion crossing 7.5% total CVD risk; within-visit swaps of single SBP readings and a single reading on the other day; with the PCE at 40–79 years, the proportion crossing 7.5% when SBP alone or all inputs were remeasured (n = 569); and model-based benchmarks that simulate independent errors of the observed size around each participant's mean (model A) or analytical error alone (model B). Instability zones are the first-visit risk ranges in which π_clin is ≥25% or ≥10%. Proportions have cluster-robust intervals over the pseudo-primary sampling units (the design's sampling units; logit scale, t distribution); contributions and curves have percentile intervals from 4,000 cluster bootstrap replicates. Study 2 outcomes were the survey-weighted proportion changing UACR-model category when the first-morning specimen replaced the random one, with Taylor-linearization intervals (16 df).")
    h2('Post Hoc Analyses')
    p(f"Post hoc analyses were added after the prespecified results were known; those under dated protocols saved before computation are labelled PH-P in Table 2 where tabulated, and all were audited independently, with departures recorded in protocol addenda (Supplemental Methods, which also describe smaller items such as examiner clustering and the blood pressure − lipid contrast). (1) The 2025 guideline's rule for starting antihypertensive medication (stage 2; or stage 1 with diabetes, chronic kidney disease or 10-year CVD risk ≥7.5%) was applied to each examination's office readings of the {x3['n_untreated_eligible']} untreated participants ({X2['E3']['primary']['excluded_missing_dbp']} lacked a diastolic reading), without the guideline's confirmation step. (2) The 2026 dyslipidemia guideline's primary prevention rules, checked against the guideline's full text, were applied to each examination of the {V['n']} participants not taking a statin ({X3['flow']['tg_over_800_excluded'] + X3['flow']['tg_missing_excluded']} excluded for triglycerides >800 mg/dL or missing), with LDL-C by the Sampson equation,[[sampson2020]] including the pathway that qualifies adults aged 30–59 years with 10-year risk <3% (LDL-C ≥160 mg/dL or 30-year ASCVD risk ≥10%); sensitivity analyses used Friedewald LDL-C and held diabetes fixed. Single-examination recommendations were also compared with those from the mean of both examinations. (3) A measurement-error model estimated the disagreement between a single-visit category and the category of the person's short-term mean level, the average the person would show over many days within about 2 weeks (κ in the protocols), from the two-visit differences and a nonparametric maximum likelihood distribution of mean levels. (4) The same model gave the expected net benefit forfeited when a risk-threshold decision is made from one visit rather than the short-term mean. Net benefit counts events prevented among those treated minus harm-weighted treatment of those without an event, with the guideline threshold as the benefit–harm exchange rate,[[vickers2006]] in net true-positive units; the loss is expressed as a share of the net benefit achievable by deciding on the short-term mean relative to treating no one, and per 1,000 assessed. Thresholds were 10-year ASCVD 3%, 5% and 10% (statin-naive, n = {X5['ascvd10']['n']}), 10-year total CVD 7.5% (not on antihypertensive medication, n = {X5['cvd10_bp']['n']}) and 30-year ASCVD 10% (ages 30–59, n = {X5['ascvd30']['n']}); strategies were one visit, the average of two days, and a second day only when the first estimate lay in the ≥25% zone, with sensitivity analyses for the error model and for a longer-term mean. Intervals for (3) and (4) come from 1,000 cluster bootstrap replicates refitted from a uniform start and cover sampling uncertainty under the model only. (5) Repeat-measurement strategies (2 or 3 days of all inputs, blood pressure or laboratory inputs; a second day only within a zone) were simulated under model A with 1,000 pairs of independent assessments per participant, the outcome being the proportion whose category differs between two assessments. (6) Laboratory-only remeasurement was repeated in the NHANES 2001–2002 second examination (n = 271; 6–47 days); the Study 2 specimen effect was recomputed after removing the average specimen ratio and compared with a within-visit SBP reading swap (reading 1 replaced by reading 2) in the same participants; and the Study 1 curves were applied to US adults in NHANES 2021–2023 (exploratory). (7) A further protocol, written after an independent review of this manuscript, added zone-limit intervals, the loss per 1,000 persons in a zone, an exchange-rate sensitivity analysis, θ by interval between examinations, complete versus incomplete eligible participants, and model A with modern laboratory variation and scaled SBP error (Supplemental Tables S39–S41). Intervals clustered on the 13 first-examination physician teams are reported as an alternative to the design clusters. The mean-level and net-benefit analyses assume calibrated risk and are reported as model-based.")
    return b

def results():
    b = []
    p = lambda s: b.append(('p', s))
    h2 = lambda s: b.append(('h2', s))
    a = lambda k, c='analysis_759': t1[k][c]
    h2('Participants')
    nhw = cvi['non_hispanic_white']
    p(f"The {pr['n']} participants had a mean age of {F(a('age')['mean'])} years, {F(a('female')['pct'])}% were women, and the median first-visit PREVENT-ASCVD risk was {F(a('risk')['median'], 2)}% (interquartile range {F(a('risk')['q1'], 2)}–{F(a('risk')['q3'], 2)}%). Compared with the weighted eligible NHANES III population, they were older and more often Black or Mexican American, and the 220 eligible participants without a complete pair were similar except for being less often non-Hispanic White ({nhw['incomplete_pct']:.0f}% vs {nhw['complete_pct']:.0f}%; Table 1; Supplemental Table S40). Between examinations, SBP varied by a within-person SD of {F(S7['sbp']['sd_w'])} mm Hg, total cholesterol by {F(S7['tc']['cvw_total_pct'])}% and creatinine by {F(S7['scr_cal']['cvw_total_pct'])}% (Table 1), close to the values Lacher and colleagues derived from the same NHANES III repeat subsample, which checks data processing rather than representativeness (Supplemental Table S10).")
    h2('Primary Outcome')
    p(f"The base PREVENT-ASCVD category differed between examinations for {pr['events']} participants ({cis(pr)}; physician-clustered interval {cin(X2['E5']['visit1_physician'])}, post hoc), {pr['up']} to a higher and {pr['down']} to a lower category; {S5['non_adjacent']} moved more than one category (Figure 1A and 1B). Standardized to the eligible population, {P(K4['theta_std'])}% (95% CI {P(K4['theta_std_ci'][0])}–{P(K4['theta_std_ci'][1])}%) would change. θ did not increase with the interval between examinations ({P(tert[0]['estimate'])}%, {P(tert[1]['estimate'])}% and {P(tert[2]['estimate'])}% at {tert[0]['days_min']:.0f}–{tert[0]['days_max']:.0f}, {tert[1]['days_min']:.0f}–{tert[1]['days_max']:.0f} and {tert[2]['days_min']:.0f}–{tert[2]['days_max']:.0f} days; odds ratio per 10 days {trend['or']:.2f}, 95% CI {trend['or_ci'][0]:.2f}–{trend['or_ci'][1]:.2f}; post hoc). On the continuous scale, a second estimate had to be more than {P(rcv[1], 0)}% higher or {P(-rcv[0], 0)}% lower than the first to exceed test-retest variation (RCV). Prespecified sensitivity analyses gave similar results (Supplemental Table S15 and Figure S6); with uncalibrated creatinine, {P(sa4a['estimate'])}% changed category.")
    h2('Where the Changes Occur')
    p(f"The modelled chance of a different category at the second examination was {100 * min(pi0):.0f}–{100 * max(pi0):.0f}% for a first-visit risk at the 3%, 5% and 10% thresholds (pointwise 95% CIs from {100 * PKLO:.0f}% to {100 * PKHI:.0f}%), and was ≥25% only within about {ZTXT} and ≥10% within about {zr('3.0', '0.1')}, {zr('5.0', '0.1')} and {zr('10.0', '0.1')}% (Figure 1C; limit intervals post hoc, Supplemental Table S39). {P(SH25['fixed_zone_share'])}% of participants ({P(SH25['ci_zone_and_sampling'][0])}–{P(SH25['ci_zone_and_sampling'][1])}%, allowing for zone uncertainty; post hoc) had a first-visit risk in a ≥25% zone. For the 7.5% total-CVD threshold (post hoc; {ZA['cvd75_curve']['events']} crossings), the chance of crossing was {100 * ZA['cvd75_curve']['peak_pi_at_threshold']:.0f}% at the threshold (95% CI {100 * ZA['cvd75_curve']['peak_ci'][0]:.0f}–{100 * ZA['cvd75_curve']['peak_ci'][1]:.0f}%), too imprecise to define a zone (a ≥25% zone existed in only {100 * (1 - Z75['empty_replicates'] / Z75['replicates']):.0f}% of replicates; the point-estimate zone, {Z75['point'][0]:.1f}–{Z75['point'][1]:.1f}%, is used below). Conditioning on the mean of both visits (no regression to the mean) gave nearly identical ≥25% zones (Figure 1D). The modelled disagreement between a single-visit category and the short-term-mean category was {P(x4['primary']['kappa'])}% (95% CI {P(kci[0])}–{P(kci[1])}%; {P(min(kap_all))}–{P(max(kap_all))}% across error models), above the model-free floor of θ/2 = {P(x4['lower_bound_theta_half'])}% (post hoc, model-based).")
    h2('Sources of Change')
    p(f"Blood pressure contributed {psi('BP')} of the {P(pr['estimate'])} pp, lipids {psi('LIPID')}, HbA1c (through the 6.5% criterion, an upper bound because diabetes status was remeasured) {psi('GLYC')} and creatinine {psi('KIDNEY')} (Figure 2A). Blood pressure ranked first in {P(K2['Psi']['BP']['rank_first_freq'], 0)}% of bootstrap replicates, but its margin over lipids was imprecise ({F(X2['E6']['psi_bp_minus_lipid_pp'])} pp; 95% CI {rng(X2['E6']['ci_pp'][0], X2['E6']['ci_pp'][1], 1, 1)}; post hoc), and on the continuous scale lipids and blood pressure accounted for similar shares of the change in the linear predictor ({P(K2['continuous']['LIPID']['pi'])}% and {P(K2['continuous']['BP']['pi'])}%; Figure 2C). Remeasuring the laboratory inputs changed the category beyond blood pressure alone ({cpi(K2['theta_minus_BP_sym'])}). For blood pressure, a single reading on another day changed the category for {P(S8['base']['c_v1r2_vs_v2r2']['estimate'])}%, against {P(S8['base']['b_v1_r2_vs_r3']['estimate'])}–{P(S8['base']['a_v1_r1_vs_r2']['estimate'])}% for swapping readings within a visit (Figure 3A). Analytical error alone reproduced {S12['B_base_low_cva']['ratio_to_Dsym_lab']:.2f}–{S12['B_base_high_cva']['ratio_to_Dsym_lab']:.2f} of the observed laboratory-only proportion (upper confidence limits {S12['B_base_low_cva']['ratio_ci'][1]:.2f} and {S12['B_base_high_cva']['ratio_ci'][1]:.3f}, the second meeting the prespecified <0.5 criterion narrowly), so most laboratory-driven change was biological or pre-analytical (Figure 2D). With UACR included and remeasured, {P(K1['theta_U']['estimate'])}% changed UACR-model category ({S(100 * dlu['estimate'])} pp versus the base model; 95% CI {rng(dlu['lower'], dlu['upper'])}; inconclusive), and urine contributed {psi('URINE', 'K2_uacr')} (Figure 2B).")
    h2('Guideline Recommendations')
    p(f"Among {x3['n_untreated_eligible']} participants not taking antihypertensive medication, a recommendation to start medication derived from one examination's office readings differed between examinations for {x3['theta_rx']['events']} ({cis(x3['theta_rx'])}); {x3['flips_with_stage_change']} of the {x3['flips_total']} changes involved a change in blood pressure stage and {x3['flips_stage1_both_highrisk_change']} a change in the high-risk flag within stage 1 (in {x3['flips_stage1_both_cvd75_only']} of these the 7.5% criterion alone). Blood pressure inputs accounted for {F(100 * x3['shapley']['BP']['estimate'])} of the {P(x3['theta_rx']['estimate'])} pp. A single-examination recommendation differed from the two-examination mean for {P(x3['vs_two_visit_mean']['mean_single_visit_differs'])}%. Among {V['n']} participants not taking a statin, a Class 1 recommendation under the 2026 dyslipidemia guideline changed for {V['primary_recommended_change']['events']} ({cis(V['primary_recommended_change'])}; {P(VS['sens_confirmed_dm_fixed']['primary_recommended_change']['estimate'])}% with diabetes held fixed; {P(min(sens9))}–{P(max(sens9))}% across sensitivity analyses) and whether any statin was recommended (Class 1 or 2a) for {P(V['recommended_or_reasonable_change']['estimate'])}% ({cin(V['recommended_or_reasonable_change'])}); the single-examination Class 1 status differed from the two-examination mean for {P(V['vs_two_visit_mean']['mean_single_visit_differs']['estimate'])}%. In {V['mechanisms_among_changes']['prevent_category_changed_risk_pathway_both_visits']} of the {V['primary_recommended_change']['events']} Class 1 changes, the PREVENT category crossing 5% decided the change (risk-based pathway at both examinations). Among {XA['n_A1']} participants aged 30–59 years, the 30-year ≥10% classification changed for {XA['theta30']['events']} ({cis(XA['theta30'])}); conditioning on the first examination, {XE['not_pathway_eligible_v2']['events']} of the {XE['n']} who had qualified through the 30-year pathway no longer did at the second examination ({P(XE['not_pathway_eligible_v2']['estimate'])}%) and {XN['became_pathway_eligible_v2']['events']} of the {XN['n']} who had not qualified did ({P(XN['became_pathway_eligible_v2']['estimate'])}%); both include regression to the mean (Table 2; Supplemental Tables S31, S33 and S34 and Figure S5).")
    h2('Net Benefit at Stake and Repeat Strategies')
    recs = {k: float(rec(e)) for k, e, _, _ in ETH}
    p(f"In the model, those whose single-visit decision differed from the short-term-mean decision had mean risks {e5['mean_abs_risk_gap_pp_among_disagreements']:.1f}–{e10['mean_abs_risk_gap_pp_among_disagreements']:.1f} pp from the threshold. Single-visit decisions forfeited {lf(e5)} of the achievable net benefit at the 5% statin threshold ({e5['regret_single_per_1000']:.2f} net true positives per 1,000 assessed, of {e5['achievable_nb_per_1000']:.1f} achievable), {lf(e75)} at the 7.5% blood pressure threshold ({e75['regret_single_per_1000']:.2f} per 1,000), {lf(e3)} at 3% and {lf(e30)} at the 30-year 10% threshold; at the 10% high-intensity threshold the loss was {lf(e10)} ({e10['regret_single_per_1000']:.2f} per 1,000, larger in absolute terms than at 5%), where the achievable net benefit is small ({e10['achievable_nb_per_1000']:.1f} per 1,000) and the estimate depended on the error model ({P(e10['post_audit_sens_sigma_by_age']['loss_fraction_single'])}–{P(e10['post_audit_sens_variance_inflation']['2.0']['loss_fraction_single'])}% across error models) (Figure 4A–C; Table 2). Per 1,000 persons whose first estimate lay in the 5% zone, the loss was {z5['regret_per_1000_in_zone']:.1f} net true positives ({z5['ci_uniform_start']['regret_per_1000_in_zone'][0]:.1f}–{z5['ci_uniform_start']['regret_per_1000_in_zone'][1]:.1f}), and {P(z5['share_of_single_regret_from_zone'], 0)}% of the total loss arose there; at 7.5%, {z75['regret_per_1000_in_zone']:.1f} per 1,000 in the zone (Supplemental Table S39). The intervals cover sampling uncertainty under the model only; alternative error models gave {P(e5['sens_empirical_errors']['loss_fraction_single'])}–{P(e5['sens_smooth_g']['loss_fraction_single'])}% at 5%, and valuing the decisions at an exchange rate of 3% or 7.5% instead of 5% changed the single-visit rule's net benefit relative to the short-term-mean rule by {P(-xr5[0.03]['loss_fraction_of_usual_rule_nb'])}% and {P(-xr5[0.075]['loss_fraction_of_usual_rule_nb'])}%, with intervals including zero. Averaging two days halved the loss ({P(e5['loss_fraction_two_day'])}% at 5%); a second day only when the first estimate lay in the ≥25% zone ({P(e5['targeted_fraction_remeasured'])}% of assessments at 5%, {P(e75['targeted_fraction_remeasured'])}% at 7.5%, {P(e30['targeted_fraction_remeasured'])}% at the 30-year threshold) recovered {recs['5%']:.0f}% of the loss at 5% and {recs['30-year 10%']:.0f}% at the 30-year threshold, {recs['3%']:.0f}% at 3%, {recs['10%']:.0f}% at 10% and {recs['7.5%']:.0f}% at 7.5%; at 5%, this was about {sig2(e5['extra_measurements_per_net_tp_targeted']):,} extra measurements per net true positive gained against about {sig2(e5['extra_measurements_per_net_tp_two_day']):,} for everyone. In the disagreement currency, a second day of all inputs for the {P(rs['t25_all']['repeat_workload'], 0)}% of assessments in the ≥25% zones removed {red('t25_all'):.0f}% of category disagreement between two assessments, against {red('all2'):.0f}% for everyone (Figure 4D; Supplemental Tables S27 and S35).".replace('In the disagreement currency, a second day of all inputs for the', 'In the disagreement currency, a second day of all inputs for the simulated'))
    h2('Urine Specimen (Study 2)')
    p(f"Replacing the random by the first-morning specimen changed {pa['events']} of {pa['n']:,} UACR-model categories (weighted {cis(pa)}), {plo['events']} to a lower and {phi['events']} to a higher category, a largely systematic effect: participants with both UACRs below 30 mg/g were {P(fb['estimate'], 0)}% of the cohort and {P(fbs['estimate'], 0)}% of the changes (post hoc). After removing the average specimen ratio, {P(X2['E8']['shift_removed_any']['estimate'])}% still changed category, in both directions (post hoc). Among the same participants, swapping the first SBP reading for the second changed {P(bp12['estimate'])}% against {P(ur12['estimate'])}% for the specimen (Table 2; Figure 3B).")
    h2('Transportability')
    g_obs, g_mod = (gD('observed', 1.0), gD('modern', 1.0))
    ths = [g['theta_sim'] for g in ZD['grid']]
    zt = lambda g, t='5.0': f"{g['thresholds'][t]['0.25'][0]:.1f}–{g['thresholds'][t]['0.25'][1]:.1f}%" if g['thresholds'][t]['0.25'] else 'no ≥25% zone'
    p(f"In the NHANES 2001–2002 second examination, laboratory-only remeasurement changed {P(E1['base']['theta_lab']['estimate'])}% of base categories, against {P(E1['study1_comparator']['base_lab_only_ref1']['estimate'])}% in Study 1 (Figure 3C). In the model A simulation (model-based), setting laboratory variation to modern research-protocol levels reduced the simulated proportion changing category from {P(g_obs['theta_sim'])}% to {P(g_mod['theta_sim'])}%, with the simulated 5% zone narrowing from {zt(g_obs)} to {zt(g_mod)}; with the SBP error SD also multiplied by 0.75–1.5, the eight scenarios spanned {P(min(ths))}–{P(max(ths))}% (Supplemental Table S41). Applied to US adults aged 30–79 years in 2021–2023, assuming 1988–1994 variation, {P(E2['zone_0.25']['estimate'])}% ({cin(E2['zone_0.25'])}) would have a risk in a ≥25% zone (exploratory; Supplemental Table S30). With the PCE at 40–79 years, remeasuring SBP alone or all inputs crossed 7.5% for {P(S11['cross75_sbp_only']['estimate'])}% and {P(S11['cross75_full']['estimate'])}%.[[ye2014]]")
    return b

def discussion():
    b = []
    p = lambda s: b.append(('p', s))
    p(f"In a national survey subsample reexamined under the same research protocol about 2 weeks later in 1988–1994, {P(pr['estimate'])}% of adults changed PREVENT-ASCVD category. The chance of a change was about even at the 3%, 5% and 10% thresholds and fell quickly outside narrow zones around them; blood pressure and lipids carried most of it, and the laboratory inputs added instability beyond blood pressure. The same remeasurement changed a single-examination recommendation to start antihypertensive medication for 1 in 9 untreated adults and the 2026 Class 1 statin recommendation for 1 in 15 adults not taking a statin. Measured as expected net benefit in a measurement-error model, however, single-visit decisions at the 3%, 5% and 7.5% thresholds forfeited 1% or less of what deciding on the short-term mean could achieve, and {lfs(e10)} at the 10% threshold, because the people who change decision lie within about 1 percentage point of the threshold, where treating and not treating have nearly the same expected value.")
    p(f"These results reconcile two earlier readings of the same phenomenon. Lambert and colleagues found 12% category change over 2 weeks and judged one assessment sufficient;[[lambert2002]] Reynolds and colleagues simulated the same variation and called for triplicate measurement.[[reynolds2002]] Both were right about different quantities. Category agreement of about 90% hides concentration: near a threshold, one examination assigns the category almost at random, while far from it the category is stable. Whether that matters depends on the currency. For consistency of advice and the workload of confirming or reversing recommendations, it matters for the roughly 1 in {round(1 / SH25['fixed_zone_share']):.0f} adults in this sample whose risk lay in the zones. For expected outcomes it matters little, as commentary on risk-based blood pressure treatment has also noted,[[rahimi2025]] because the same proximity that makes the category unstable makes the decision unimportant; under the exchange-rate assumption this is expected for any modest measurement error, and what the data add is the size of the loss and its growth with the error variance. Beyond earlier remeasurement studies,[[lambert2002,ye2014,ulbricht2018,ogunwale2016]] we remeasured all PREVENT inputs, including creatinine, HbA1c and urine albumin, in a national survey sample, apportioned the change among them, located it on the risk scale and quantified both currencies for current rules; the headline proportion itself is close to Lambert's.")
    p(f"The practical implication is selective and follows from the data, not from a demonstrated outcome benefit. A category or recommendation within the zones (about {ZTXT} 10-year ASCVD risk; about 9–11% 30-year risk for younger adults in the dyslipidemia guideline's new pathway) is provisional, and in the model a second measurement day for these adults recovers a quarter to a half of the small net-benefit loss and about a quarter of category disagreement for a fraction of the workload of repeating everyone. This is consistent with the blood pressure guideline's requirement for readings on two or more occasions,[[htn2025]] with office measurement studies,[[handler2012]] a measurement-error simulation[[sakhuja2022]] and commentary on the guideline's measurement dependence;[[giacona2026]] home or ambulatory confirmation and coronary artery calcium were not compared. The dyslipidemia guideline's one-profile rule can be read two ways from the same numbers: it forfeits 1% or less of achievable net benefit, which argues for keeping it, or it leaves about 1 in 15 Class 1 recommendations liable to reverse on remeasurement, which argues for repeating lipids and the risk estimate near thresholds.[[dyslipidemia2026]] The urine specimen is a different problem: a first-morning void lowered UACR systematically and moved about 5% of UACR-model categories, mostly among adults with normal albuminuria on both specimens; the specimen type should be standardized, since repeating the same specimen would not remove the offset.")
    p(f"Limitations. Measurements were made in 1988–1994 with mercury sphygmomanometers and older assays under a research protocol. The laboratory-only comparison in 2001–2002 was of similar size, and in the model A simulation modern research-protocol laboratory variation lowers the proportion changing category by about {P(gD('observed', 1.0)['theta_sim'] - gD('modern', 1.0)['theta_sim'])} pp while plausible changes in blood pressure error move it in either direction; routine care adds pre-analytical and device variation that neither era captures, so the zone limits and loss fractions are 1988–1994 research-protocol estimates, and the creatinine component is era-specific (within-person CV 8.2%). Statin use was rare (10 of 759), whereas today a quarter or more of adults aged 40–75 years take a statin, concentrated near and above the thresholds. The 2025 rule was applied to office readings from one examination, without the guideline's confirmation step. The reexamined subsample was nonrandom and unweighted, with 79 events and physician clustering; θ did not increase with the interval between examinations, the incomplete eligible participants were similar apart from race and ethnicity, and the standardized estimate and examiner-clustered intervals bound the rest, but standardization on first-visit risk assumes the same within-person variation. The attribution contrasts were imprecise; the zone limits carry intervals of about ±0.2–0.6 pp. The net-benefit analysis is model-based: it assumes PREVENT is calibrated here, although the equations were fitted to single-occasion inputs so that a 2-week mean is not exactly the quantity they were calibrated to; it treats the guideline threshold as the benefit–harm exchange rate; it defines the short-term mean over 2 weeks (doubling the error variance to represent a longer-term mean multiplied the loss by 1.5–2.6); its intervals exclude model uncertainty; and it covers the risk-threshold components of the rules, not the blood pressure stage or LDL-C cut-points. The repeat-measurement simulation assumes independent day-to-day errors, so persistent components such as a white-coat effect or season would make its reductions optimistic. Risk enhancers and coronary calcium were unavailable for the 2026 rule.")
    p('One set of routine measurements assigns a PREVENT category that about 1 in 10 adults would not receive on a second day, and the changes reach current treatment recommendations. Their expected cost in net benefit is small, as a well-placed threshold implies; their cost in consistency is not, and both are concentrated in zones narrow enough to target.')
    return b

