def table2():

    def row(lbl, e, status, n=None):
        return [lbl, f"{e.get('n', n):,}" if e.get('n', n) else '—', str(e.get('events', '—')), cip(e), status]

    def crow(lbl, e, status):
        return [lbl, str(e['n']), '—', f"{S(100 * e['estimate'])} pp ({rng(e['lower'], e['upper'])})", status]
    std = lambda k: dict(estimate=k['theta_std'], lower=k['theta_std_ci'][0], upper=k['theta_std_ci'][1])
    kap = dict(estimate=x4['primary']['kappa'], lower=kci[0], upper=kci[1])
    tv3 = x3['vs_two_visit_mean']
    tv9 = V['vs_two_visit_mean']['mean_single_visit_differs']
    c3 = tv3['mean_single_visit_differs_ci']
    c3 = (c3['lower'], c3['upper']) if isinstance(c3, dict) else tuple(c3)
    rows = [['Study 1, NHANES III reexamination (unweighted)'], row('Base PREVENT-ASCVD category changed (θ)', pr, 'P'), row('  Higher category at visit 2', S5['p_up'], 'P'), row('  Lower category at visit 2', S5['p_down'], 'P'), ['θ standardized to the eligible population', str(pr['n']), '—', cip(std(K4)), 'P'], ['Single-visit category differs from the short-term-mean category (κ in the protocols)', str(pr['n']), '—', cip(kap), 'PH, MB'], row('UACR-model category changed', K1['theta_U'], 'P'), crow('  Paired difference, UACR − base', dlu, 'P'), crow('θ minus blood-pressure-only proportion', K2['theta_minus_BP_sym'], 'P'), row('PREVENT 10-year total CVD crossed 7.5%', S10['all_759'], 'P'), ['Guideline recommendations at the two examinations'], row('2025 BP guideline: start medication (untreated; single-examination office readings)', x3['theta_rx'], 'PH-P'), ['  Single examination vs two-examination mean', str(x3['theta_rx']['n']), '—', f"{P(tv3['mean_single_visit_differs'])}% ({P(c3[0])}–{P(c3[1])})", 'PH-P'], row('2026 dyslipidemia guideline: Class 1 statin recommendation (statin-naive)', V['primary_recommended_change'], 'PH-P'), row('  Any statin recommendation (Class 1 or 2a)', V['recommended_or_reasonable_change'], 'PH-P'), ['  Single examination vs two-examination mean (Class 1)', str(V['n']), '—', cip(tv9), 'PH-P'], row('  30-year ≥10% classification changed (ages 30–59)', XA['theta30'], 'PH-P'), row('  30-year pathway: qualified at visit 1, not at visit 2', XE['not_pathway_eligible_v2'], 'PH-P'), row('  30-year pathway: not qualified at visit 1, qualified at visit 2', XN['became_pathway_eligible_v2'], 'PH-P'), ['Expected net benefit forfeited by single-visit decisions: % of achievable (95% CI); net true positives per 1,000 assessed']]
    for lab, e, pop, th in ETH:
        n = X5[pop]['n']
        c = e['ci_uniform_start']
        rows.append([f"  {('10-year ASCVD ' if pop == 'ascvd10' else '10-year total CVD ' if pop == 'cvd10_bp' else '30-year ASCVD ')}{th}%" + {'3': '', '5': ' (Class 1 statin)', '7.5': ' (BP drug threshold)', '10': ' (high intensity)' if pop == 'ascvd10' else ' (Class 2a, ages 30–59)'}[th], str(n), '—', f"{P(e['loss_fraction_single'])}% ({P(c['loss_fraction_single'][0])}–{P(c['loss_fraction_single'][1])}); {e['regret_single_per_1000']:.2f}", 'PH-P, MB'])
    recs = [float(rec(e)) for _, e, _, _ in ETH]
    zc = z5['ci_uniform_start']['regret_per_1000_in_zone']
    rows += [['  Second day only in the ≥25% zone: share of the loss recovered', '—', '—', f'{min(recs):.0f}–{max(recs):.0f}% (7.5% threshold {rec(e75)}%)', 'PH-P, MB'], ['  Loss per 1,000 persons whose first estimate lies in the 5% zone (share of the loss arising there)', str(X5['ascvd10']['n']), '—', f"{z5['regret_per_1000_in_zone']:.1f} ({zc[0]:.1f}–{zc[1]:.1f}); {P(z5['share_of_single_regret_from_zone'], 0)}%", 'PH-P, MB'], ['Study 2, NHANES 2009–2010 (survey-weighted): random to first-morning urine, UACR model'], row('Category changed', pa, 'P'), row('  Lower category with first-morning urine', plo, 'P'), row('  Higher category with first-morning urine', phi, 'P'), row('SBP reading 1 replaced by reading 2, same participants', bp12, 'PH'), row('Specimen change, same participants', ur12, 'PH')]
    return {'title': 'Table 2. Primary, Secondary and Post Hoc Estimates', 'header': ['Estimate', 'n', 'Events', 'Estimate (95% CI)', 'Status'], 'rows': rows, 'widths_in': [3.1, 0.5, 0.55, 1.9, 0.65], 'size': 8, 'note': 'Status: P, prespecified in the frozen protocol; PH, post hoc; PH-P, post hoc under a protocol recorded before computation; MB, model-based. Study 1 proportions: cluster-robust (CR1) variance over pseudo-primary sampling units with logit-scale t intervals; paired differences: cluster-robust Wald intervals. Standardized estimate: joint cluster and Rao–Wu bootstrap. Short-term-mean disagreement: measurement-error model with a nonparametric mean-level distribution; interval from 1,000 cluster bootstrap replicates' + (' refitted from a uniform start' if E4U else ' (warm-started; a uniform-start rerun is in progress)') + '. Net benefit: loss as a share of the net benefit achievable by deciding on the short-term mean relative to treating no one; intervals from 1,000 uniform-start bootstrap refits, sampling uncertainty under the model only. Guideline rows condition on the two examinations of the same person; the 30-year pathway rows condition on first-visit status and include regression to the mean. Study 2: examination weights, Taylor linearization (16 df); counts unweighted. ASCVD, atherosclerotic cardiovascular disease; BP, blood pressure; CVD, cardiovascular disease; SBP, systolic blood pressure; UACR, urine albumin-to-creatinine ratio.'}

def legends():
    return [f"Figure 1. Reclassification and where it happens (Study 1, n = {pr['n']}). A, Base PREVENT 10-year ASCVD risk at the second against the first examination (log axes) with the 3%, 5% and 10% thresholds; colored points changed category. B, Counts of first- by second-examination category. C, Modelled probability of a different category at the second examination by first-examination risk (prespecified threshold-distance model, π_clin; log x axis), with pointwise 95% cluster-bootstrap intervals (4,000 replicates); shading marks the zones where the probability is ≥25% (limits with their intervals in Supplemental Table S39); the probability conditions on the first examination and includes regression to the mean. D, The same model conditioned on the mean of both examinations by logit distance from the nearest threshold, one curve per nearest threshold, with observed proportions in distance bins (changes/participants) and the closed-form probability that the change in the linear predictor exceeds twice the distance; the upper axis gives the equivalent distance above the 5% threshold in percentage points.", f"Figure 2. Sources of category change (Study 1). A and B, Symmetrized Shapley contributions of each input group to the proportion changing category, which sum to θ (base model, n = {pr['n']}) or to the UACR-model proportion (n = {K1['theta_U']['n']}), with 95% cluster-bootstrap intervals; HbA1c acts through the 6.5% diabetes criterion. C, Share of the mean squared change in the PREVENT linear predictor attributable to each group: the fraction of the squared between-examination change in the continuous risk score that each group's inputs account for, which weights large shifts regardless of whether a threshold is crossed. D, Model-based benchmarks: observed θ; simulated θ with independent errors of the observed size (model A); the observed proportion changing when only the laboratory inputs are remeasured (symmetrized over both reference examinations, {100 * S12['D_sym_lab_observed']:.1f}%; the first-examination reference gives {P(E1['study1_comparator']['base_lab_only_ref1']['estimate'])}%); and simulated analytical error alone (model B) at the low and high ends of the analytical-CV bracket.", f"Figure 3. Category change by source of measurement variation, by study design (percent with 95% CI). A, Study 1 (NHANES III, unweighted; cluster-robust intervals): swapping SBP readings within a visit, a single input group remeasured on the other day (open circles: single-group swaps from the attribution with the first examination as reference, no interval), the laboratory inputs with blood pressure fixed, and all inputs. B, Study 2 (NHANES 2009–2010, survey-weighted): replacing SBP reading 1 by reading 2 and the random by the first-morning urine specimen in the same {bp12['n']:,} participants, and the specimen change in all {pa['n']:,} participants (UACR model). C, NHANES 2001–2002 repeat sample (post hoc; n = {E1['base']['theta_lab']['n']} for the laboratory rows, {ex['n']} for the urine row): random urine at two examinations, laboratory-only remeasurement, and laboratory inputs with UACR. Rows use the base equation unless labelled UACR model. Estimates differ in era, equation, weighting and sample and were not compared formally.", f"Figure 4. Decisions, net benefit at stake and repeat strategies (Study 1; model-based). A, Expected net benefit forfeited, as a percentage of the net benefit achievable by deciding on the short-term mean risk relative to treating no one, when the risk-threshold decision is made from a single visit, from the average of two days, or from a second day only when the first estimate lies in the ≥25% zone; thresholds are the 2026 dyslipidemia guideline's 3%, 5% (Class 1) and 10% (high intensity) 10-year ASCVD and 10% 30-year ASCVD (Class 2a, ages 30–59) cut-points and the 2025 blood pressure guideline's 7.5% 10-year total CVD cut-point (statin users excluded, n = {X5['ascvd10']['n']}, without the triglyceride exclusion of the statin-rule analysis; not on blood pressure medication, n = {X5['cvd10_bp']['n']}; aged 30–59 without statin, n = {X5['ascvd30']['n']}); intervals are 95% percentiles from 1,000 cluster bootstrap replicates refitted from a uniform start (sampling uncertainty under the model only). B, The same single-visit loss in net true positives per 1,000 assessed (bars, with intervals), with the achievable net benefit per 1,000 printed beside each bar. C, Sensitivity of the single-visit loss to the error model: error SD estimated within age bands; error variance relative to a longer-term mean inflated 1.5- and 2-fold. D, Simulated reduction in category disagreement between two independent assessments against additional measurement days per person, for repeating all inputs, blood pressure or laboratory inputs on 2 or 3 days (filled) or only for participants in the ≥10% or ≥25% zone (open), with 95% cluster-bootstrap intervals (simulation SDs fixed; independent day-to-day errors assumed). The net-benefit model assumes calibrated risk and the threshold as the benefit–harm exchange rate; the short-term mean is the average over the 2-week process."]

def build(check=False):
    abs_ = abstract()
    front = [('h1', 'Abstract')] + [('p', s) for s in abs_] + [('h1', 'Clinical Perspective')] + clinical_perspective() + [('h1', 'Nonstandard Abbreviations and Acronyms'), ('small', ABBREV)]
    main = [('h1', 'Introduction')] + [('p', s) for s in intro()] + [('h1', 'Methods')] + methods() + [('h1', 'Results')] + results() + [('h1', 'Discussion')] + discussion() + declarations()
    t1a, t1b = M.table1()
    t1a['title'] = 'Table 1. Study 1: Characteristics of Participants and Repeatability of Inputs'
    t1b['title'] = 'Table 1 (continued). B. Inputs at Each Examination'
    tables = [('break',), ('table', t1a), ('break',), ('table', t1b), ('break',), ('table', table2())]
    figs = [('break',), ('h1', 'Figure Legends')] + [('legend', s) for s in legends()]
    OUT.mkdir(exist_ok=True)
    from PIL import Image
    for i in range(1, 5):
        Image.open(FIG7 / f'fig{i}.png').convert('RGB').save(OUT / f'figure_{i}.png', dpi=(300, 300))
        shutil.copy2(FIG7 / f'fig{i}.svg', OUT / f'figure_{i}.svg')
    figblocks = [('break',)] + sum([[('figure', OUT / f'figure_{i}.png', f'Figure {i}', 6.3), ('break',)] for i in range(1, 5)], [])[:-1]
    all_blocks = [('title', TITLE)] + front + main + tables + figs
    order = W.number_citations(all_blocks)
    text_blocks = [('p', s) for s in intro()] + methods() + results() + discussion()
    cp = clinical_perspective()
    cp_new = para_words([b[1] for b in cp[1:4]])
    cp_imp = para_words([b[1] for b in cp[5:]])
    stats = {'abstract_words': para_words(abs_), 'main_text_words': W.words(text_blocks), 'clinical_perspective_words': {'what_is_new': cp_new, 'implications': cp_imp, 'limit_each': 100}, 'references': len(order), 'tables': 2, 'figures': 4, 'e4_uniform_ci_used': E4U is not None, 'limits': {'venue': 'Circulation Original Research', 'text_words_max': 4000, 'abstract_max': 300, 'displays_max': 6, 'references_max': 50}, 'section_words': {'introduction': para_words(intro()), 'methods': W.words(methods()), 'results': W.words(results()), 'discussion': W.words(discussion())}}
    print(json.dumps(stats))
    if check:
        txt = [W.render_cites(x[1], order) for x in [('title', TITLE)] + front + main if x[0] in ('p', 'h1', 'h2', 'title', 'small')]
        (OUT / 'draft_text_check.txt').write_text('\n\n'.join(txt) + '\n\nREFERENCE KEYS: ' + ', '.join(sorted(order, key=order.get)), encoding='utf-8')
        return stats
    refs = [ref_text(k) for k in sorted(order, key=order.get)]
    doc = W.new_doc(TITLE)
    W.render(doc, [('title', TITLE)], order)
    for s in ['Yunhao Jiang', 'The University of Edinburgh, Edinburgh, United Kingdom', 'Correspondence: Yunhao Jiang; biojiang777@gmail.com', f'Short title: {SHORT}', f"Word count: abstract {stats['abstract_words']}; text {stats['main_text_words']} (Introduction to Discussion). Tables 2; figures 4; references {stats['references']}."]:
        W.para(doc, s)
    W.page_break(doc)
    W.render(doc, front + main, order)
    W.para(doc, 'References', style='Heading 1')
    W.render(doc, [('refs', refs)], order)
    W.render(doc, tables + figs + figblocks, order)
    W.add_line_numbers(doc)
    out = OUT / 'nh3_manuscript_v7_circulation.docx'
    doc.save(out)
    srcs = [PH / 'ext3_statin_results.json', PH / 'ext4_30yr_results.json', PH / 'ext5_stakes_results.json', PH / 'ext6_review_results.json', PH / 'ext2_results.json', M.A1 / 'stage3/stage3_results.json', M.EV / 'study2_evidence.json', ST / 'EVIDENCE_LEDGER.md'] + ([PH / 'ext2_e4_uniform_ci.json'] if E4U else [])
    rec_ = {'revision': 7, 'draft': 2, 'venue': 'Circulation Original Research (prepared; user has not fixed the venue)', 'stats': stats, 'reference_order': sorted(order, key=order.get), 'built_from': {str(p.relative_to(ROOT)): hashlib.sha256(p.read_bytes()).hexdigest() for p in srcs}, 'notes': ['Draft 2 (2026-10-11): applies the referee and fidelity reviews of draft 1 (review_dispositions_v7.md) and the E12 analyses (extensions6_protocol_20261011.md).', 'Displays: Table 1 (A, B), Table 2, Figures 1-4 (figures_v7; Figure 3 is the ladder by design). Central Illustration dropped unless Circulation requires a graphical abstract.', 'The parked research letter is no longer cited; E9/E10 detail is in Supplemental Tables S33-S34 and Figure S5.', 'kappa interval: ' + ('uniform-start rerun (ext2_e4_uniform_ci.json)' if E4U else 'ORIGINAL WARM-START CI, PENDING RERUN')], 'author_actions': ['Confirm venue; recheck the Circulation author instructions (Clinical Perspective, graphical abstract, abbreviations, reference style).', 'Supply code/data repository link.', 'Decide whether the parked letter is ever submitted (overlap disclosure in letter_2026_statin/STATUS.md).']}
    (OUT / 'build_record.json').write_text(json.dumps(rec_, indent=1) + '\n', encoding='utf-8')
    print('saved', out)
if __name__ == '__main__':
    build(check='--check' in sys.argv)
